begin;
select extensions.no_plan();
select extensions.ok(not (select enabled from app_private.sofascore_collection_settings where id),'unattended collection ships disabled');
select extensions.ok(not has_function_privilege('authenticated','api.service_sofascore_collection_claim(uuid)','execute'),'authenticated users cannot claim collection work');
select extensions.ok(not has_function_privilege('service_role','app_private.sofascore_collection_configure(boolean)','execute'),'service role cannot activate collection');
select extensions.ok(has_function_privilege('service_role','api.service_sofascore_collection_commit(uuid,uuid,jsonb,jsonb)','execute'),'the fenced recorder is service-only');
select extensions.ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='app_private.sofascore_collection_settings'::regclass),'private settings force RLS');
select extensions.ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='app_private.sofascore_collection_queue'::regclass),'durable queue forces RLS');
select extensions.ok(not exists(select 1 from cron.job where command ilike '%collection%' and active),'migration activates no new cron job');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select extensions.is(api.service_sofascore_collection_claim('a1000000-0000-4000-8000-000000000999')->>'status','disabled','a stray scheduled request cannot run while off');
select extensions.ok(not api.service_sofascore_collection_reserve('a1000000-0000-4000-8000-000000000999'),'no request may leave without a lease');
update app_private.sofascore_collection_settings set enabled=true,holder='a1000000-0000-4000-8000-000000000999',lease_until=now()+interval '4 minutes',reserved_calls=1599,lease_calls=7,quota_month=date_trunc('month',now())::date where id;
select extensions.ok(api.service_sofascore_collection_reserve('a1000000-0000-4000-8000-000000000999'),'last available monthly and pass slot can be reserved');
select extensions.ok(not api.service_sofascore_collection_reserve('a1000000-0000-4000-8000-000000000999'),'1600 monthly / eight-per-pass cap prevents another request');
select extensions.is((select reserved_calls from app_private.sofascore_collection_settings where id),1600,'refused reservations cannot grow the counter');
select extensions.ok(not api.service_sofascore_collection_reserve('a1000000-0000-4000-8000-000000000998'),'an old holder cannot consume a successor budget');
update app_private.sofascore_collection_settings set reserved_calls=0,lease_calls=0,lease_until=now()-interval '1 second' where id;
select extensions.ok(not api.service_sofascore_collection_reserve('a1000000-0000-4000-8000-000000000999'),'expired leases cannot send requests');
update app_private.sofascore_collection_settings set lease_until=now()+interval '4 minutes' where id;
insert into app_private.rapidapi_call_counts(day,job,endpoint,status_code,calls) values(current_date,'collection_budget_test','matches/detail',200,9000);
select extensions.ok(not api.service_sofascore_collection_reserve('a1000000-0000-4000-8000-000000000999'),'global monthly 9000 stop includes other jobs');
select extensions.throws_ok($$select api.service_sofascore_collection_commit('a1000000-0000-4000-8000-000000000998','a1000000-0000-4000-8000-000000000100',null,'{"code":"collected"}')$$,'P0001','collection_lease_lost','stale workers are fenced before observation writes');
select extensions.ok((app_private.sofascore_collection_health()->>'detail')::jsonb ? 'lastSuccessfulCollectionAt','existing ops monitoring includes last successful capture');
select extensions.ok((select prosrc like '%football_refresh_invoke%' from pg_proc where oid='app_private.football_season_refresh_tick()'::regprocedure),'the existing scheduler dispatches the unattended collector');
select * from extensions.finish();
rollback;
